def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_opp = opp[-1]
    last_me = my[-1]

    opp_c = opp.count('C')
    opp_d = n - opp_c

    run_d = 0
    for a in reversed(opp):
        if a == 'D':
            run_d += 1
        else:
            break

    our_d_streak = 0
    for a in reversed(my):
        if a == 'D':
            our_d_streak += 1
        else:
            break

    last10 = opp[-10:]
    recent_d10 = last10.count('D')
    recent_c10 = len(last10) - recent_d10

    hard = (
        (n >= 10 and recent_d10 >= 7) or
        (opp_d * 2 > n) or
        (run_d >= 9) or
        (n < 8 and opp_d >= 4)
    )

    punished = 0
    not_punished = 0
    our_D_trans = 0
    for i in range(1, n):
        if my[i - 1] == 'D':
            our_D_trans += 1
            if opp[i] == 'D':
                punished += 1
            else:
                not_punished += 1

    coopish = (opp_c * 3 >= n * 2) or (n >= 10 and recent_c10 >= 6)
    exploit = False
    if n >= 6 and coopish:
        if punished == 0 and not_punished >= 1:
            exploit = True
        elif not_punished >= 2 and punished * 2 <= not_punished:
            exploit = True

    if exploit and last_opp == 'C':
        return 'D'

    if last_opp == 'D':
        if n <= 3 and run_d == 1:
            return 'C'

        if hard:
            return 'D'

        if run_d == 1:
            if last_me == 'D':
                return 'C'
            if opp_c * 5 >= n * 4 and opp_d <= 1:
                return 'C'
            return 'D'

        if last_me == 'C':
            if (
                n >= 2 and my[-2] == 'D' and
                run_d >= 4 and opp_c > opp_d and not hard
            ):
                return 'C'
            return 'D'

        if our_d_streak >= 3 and opp_c > opp_d and not hard and run_d <= 6:
            return 'C'
        return 'D'

    if last_me == 'C' and n < 96:
        if opp_c == n and our_D_trans == 0 and n >= 30:
            return 'D'

    return 'C'
